// Timelock puzzle: sequential hashing that cannot be parallelized
const c=require('node:crypto');
let h="sig-timelock-001";
const N=700;
for(let i=0;i<N;i++)h=c.createHash('sha256').update(h).digest('hex');
console.log('after '+N+' sequential hashes:',h.slice(0,24)+'… (inherently sequential)');

